// The CycloneDX SBOM of one image, for one deploy.
//
// Generated by the same pinned Trivy container image the image scanner already
// runs (imageScan.js SCANNER_IMAGE, the docker socket and the shared cache), so
// no new tool is installed. Measured on aquasec/trivy:0.74.0 against a locally
// built alpine + npm image: `image --format cyclonedx` writes CycloneDX 1.7 JSON
// to stdout in ~2s with a warm cache and no vulnerability database (the SBOM
// needs none), with per-component licenses, purls, dependencies and a SHA-1
// hash on every package it found. It is pointed at the image ID, not the tag,
// so the bytes described are the bytes that will be signed.
//
// Then enriched toward the CISA 2026 minimum elements: author, generation
// context, the amending tool, the app/commit/lockfile context, a SHA-256 for
// the image itself, and an explicit "unknown" where a component has no license
// or no hash (CISA: "explicitly state whether the information is unknown").
// Trivy's 1.7 output is labelled 1.6: every field it emits exists in 1.6.

import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { join, resolve } from 'node:path';
import { SCANNER_IMAGE, ensureScanner } from '../imageScan.js';
import { OOM_APP_FLAG } from '../oomPriority.js';
import { CPU_APP_FLAG } from '../cpuPriority.js';

const execFileAsync = promisify(execFile);

export const SBOM_SPEC_VERSION = '1.6';
export const SBOM_SCHEMA = 'http://cyclonedx.org/schema/bom-1.6.schema.json';
// CycloneDX lifecycle phase. Trivy reads the finished image, which CycloneDX
// calls post-build and CISA calls "after build" (binary analysis).
export const GENERATION_PHASE = 'post-build';
const SBOM_TIMEOUT_MS = 5 * 60 * 1000;
const SBOM_MAX_BUFFER = 128 * 1024 * 1024;
const DOCKER_SOCKET = '/var/run/docker.sock';

function cacheDir() {
  return join(resolve(process.env.DATA_DIR || './data'), 'trivy-cache');
}

/**
 * Run Trivy against one image id. Never throws.
 * @returns {Promise<{ ok: boolean, bom?: object, error?: string, skipped?: boolean }>}
 */
export async function runSbomTool(imageId, { allowPull = false } = {}) {
  const scanner = await ensureScanner({ allowPull });
  if (!scanner.ok) return { ok: false, skipped: true, error: scanner.reason };
  let stdout;
  try {
    ({ stdout } = await execFileAsync('docker', [
      'run', '--rm', OOM_APP_FLAG, CPU_APP_FLAG,
      '-v', `${DOCKER_SOCKET}:${DOCKER_SOCKET}`,
      '-v', `${cacheDir()}:/root/.cache/trivy`,
      SCANNER_IMAGE, 'image', '--quiet', '--format', 'cyclonedx',
      '--timeout', `${Math.floor(SBOM_TIMEOUT_MS / 1000) - 10}s`,
      imageId,
    ], { timeout: SBOM_TIMEOUT_MS, maxBuffer: SBOM_MAX_BUFFER }));
  } catch (err) {
    const detail = (err.stderr || err.message || '').trim().split('\n').slice(-3).join(' ');
    return { ok: false, error: `SBOM generation failed for ${imageId}: ${detail || 'no output'}` };
  }
  let bom;
  try { bom = JSON.parse(stdout); } catch (e) { return { ok: false, error: `SBOM tool returned unparseable output: ${e.message}` }; }
  if (bom?.bomFormat !== 'CycloneDX') return { ok: false, error: `SBOM tool returned ${JSON.stringify(bom?.bomFormat)}, expected CycloneDX` };
  return { ok: true, bom };
}

function walk(components, fn) {
  for (const c of components || []) {
    fn(c);
    if (Array.isArray(c.components)) walk(c.components, fn);
  }
}

function prop(name, value) { return { name, value: String(value) }; }

/** The image id Trivy says it described, from metadata.component properties. */
export function describedImageId(bom) {
  return (bom?.metadata?.component?.properties || []).find((p) => p.name === 'aquasecurity:trivy:ImageID')?.value || null;
}

/**
 * Per-field coverage of the CISA component elements. Hashes are counted per
 * algorithm because CISA asks for a NIST-approved one and Trivy gives SHA-1.
 */
export function sbomCoverage(bom) {
  const c = { components: 0, withHash: 0, withSha256: 0, hashAlgorithms: {}, withLicense: 0, withIdentifier: 0, withVersion: 0 };
  walk(bom?.components, (x) => {
    c.components += 1;
    const hashes = Array.isArray(x.hashes) ? x.hashes.filter((h) => h?.alg && h?.content) : [];
    if (hashes.length) c.withHash += 1;
    if (hashes.some((h) => h.alg === 'SHA-256')) c.withSha256 += 1;
    for (const h of hashes) c.hashAlgorithms[h.alg] = (c.hashAlgorithms[h.alg] || 0) + 1;
    if (Array.isArray(x.licenses) && x.licenses.some((l) => l?.license?.id || l?.license?.name || l?.expression)) c.withLicense += 1;
    if (x.purl || x.cpe || x.swid) c.withIdentifier += 1;
    if (x.version) c.withVersion += 1;
  });
  return c;
}

/**
 * Enrich a Trivy CycloneDX document with what AppCrane knows. Pure.
 * @param {object} bom
 * @param {{ author: string, appcraneVersion: string, app: { slug: string, name?: string }, env: string,
 *           deploymentId: number|null, imageRef: string, imageId: string, repoDigest?: string|null,
 *           commitSha?: string|null, lockfile?: { name: string, sha256: string|null }|null, origin?: string }} ctx
 */
export function enrichSbom(bom, ctx) {
  const out = structuredClone(bom);
  out.$schema = SBOM_SCHEMA;
  out.specVersion = SBOM_SPEC_VERSION;
  out.version = Number.isInteger(out.version) ? out.version : 1;
  const md = out.metadata = out.metadata || {};
  md.timestamp = md.timestamp || new Date().toISOString();
  md.lifecycles = [{ phase: GENERATION_PHASE }];
  md.authors = [{ name: ctx.author }];
  md.tools = md.tools && !Array.isArray(md.tools) ? md.tools : { components: [] };
  md.tools.components = Array.isArray(md.tools.components) ? md.tools.components : [];
  md.tools.components.push({ type: 'application', name: 'AppCrane', version: ctx.appcraneVersion, description: 'amended the SBOM with deploy context and signed it' });
  const comp = md.component = md.component || { type: 'container', name: ctx.imageRef };
  const imageHex = String(ctx.imageId).replace(/^sha256:/, '');
  comp.hashes = [...(Array.isArray(comp.hashes) ? comp.hashes : []).filter((h) => h.alg !== 'SHA-256'), { alg: 'SHA-256', content: imageHex }];
  const lock = ctx.lockfile || null;
  md.properties = [
    ...(Array.isArray(md.properties) ? md.properties : []),
    prop('appcrane:app', ctx.app.slug),
    prop('appcrane:env', ctx.env),
    ...(ctx.deploymentId != null ? [prop('appcrane:deployment_id', ctx.deploymentId)] : []),
    prop('appcrane:origin', ctx.origin || 'deploy'),
    prop('appcrane:image_ref', ctx.imageRef),
    prop('appcrane:image_id', ctx.imageId),
    ...(ctx.repoDigest ? [prop('appcrane:repo_digest', ctx.repoDigest)] : []),
    prop('appcrane:commit_sha', ctx.commitSha || 'unknown'),
    prop('appcrane:lockfile', lock ? lock.name : 'unknown'),
    prop('appcrane:lockfile_sha256', lock?.sha256 || 'unknown'),
    prop('cisa:generation_context', 'after build (binary analysis of the built image, before it runs)'),
  ];
  walk(out.components, (x) => {
    const unknown = [];
    if (!(Array.isArray(x.licenses) && x.licenses.length)) unknown.push('license');
    if (!(Array.isArray(x.hashes) && x.hashes.length)) unknown.push('hash');
    if (!x.supplier && !x.manufacturer && !x.publisher && !x.authors) unknown.push('producer');
    if (unknown.length) x.properties = [...(Array.isArray(x.properties) ? x.properties : []), prop('cisa:unknown', unknown.join(','))];
  });
  return out;
}
